// Identity is verified only by the explicitly reviewed catalog. Search matches stay candidates.
export const reviewedImages={
 '3485264':[{title:'Goldstone radar sequence of 2010 AL30',type:'Radar imagery',src:'assets/2010al30-radar.gif',source:'https://echo.jpl.nasa.gov/asteroids/2010AL30/2010al30.html',credit:'NASA/JPL Goldstone Solar System Radar',date:'January 2010',caption:'Delay-Doppler radar sequence. These are radar measurements, not a visible-light photograph. The historical observation is unrelated to the selected encounter date.'}],
 '2101955':[{title:'Bennu ejecting particles',type:'Spacecraft image composite',src:'assets/bennu-particles.jpg',source:'https://www.jpl.nasa.gov/images/pia23554-asteroid-bennu-particles/',credit:'NASA/Goddard/University of Arizona/Lockheed Martin',date:'January 6, 2019',caption:'Processed combination of two OSIRIS-REx NavCam exposures showing Bennu and particles. Historical imagery, not a live camera.'}],
 '2099942':[{title:'Radar observations of Apophis',type:'Radar imagery',src:'https://images-assets.nasa.gov/image/PIA24168/PIA24168~small.jpg',source:'https://www.jpl.nasa.gov/images/pia24168-radar-observations-of-asteroid-99942-apophis/',credit:'NASA/JPL-Caltech and NSF/AUI/GBO',date:'March 8–10, 2021',caption:'Goldstone / Green Bank radar observations of Apophis. Historical radar data, not a visible-light photo or a live camera.'}]
};
export function searchDesignation(row){const designation=row.name.match(/\b(?:18|19|20)\d{2}\s+[A-Z]{1,2}\d*\b/);if(designation)return designation[0];return row.name.replace(/^[0-9]+\s*/,'').replace(/[()]/g,'').trim()||row.name;}
const plain=s=>String(s??'').replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim();
export function safeNasaImage(url){try{const u=new URL(url);return u.protocol==='https:'&&(u.hostname==='images-assets.nasa.gov'||u.hostname.endsWith('.nasa.gov'))&&!u.username&&!u.password;}catch{return false;}}
export function imageCandidates(payload,designation){
 const words=designation.match(/[a-z0-9]+/gi);if(!words?.length)return [];const identity=new RegExp('\\b'+words.join('[\\s_-]*')+'\\b','i');
 return (payload?.collection?.items??[]).flatMap(item=>{const d=item.data?.[0],src=item.links?.find(l=>l.rel==='preview'&&safeNasaImage(l.href))?.href;if(!d||d.media_type!=='image'||!src)return [];const title=plain(d.title),description=plain(d.description),text=title+' '+description;if(!identity.test(text))return [];const illustrative=/artist|illustration|concept|simulation|simulated|rendering|orbit(?:al)? diagram/i.test(title+' '+description);return [{id:String(d.nasa_id),title,src,source:'https://images.nasa.gov/details/'+encodeURIComponent(d.nasa_id),credit:plain(d.photographer||d.secondary_creator||d.center||'NASA Image and Video Library'),date:plain(d.date_created).slice(0,10),description:description.slice(0,450),illustrative}];}).slice(0,4);
}
const results=new Map(),pending=new Map();
export async function lookupImages(row,fetcher=fetch){const query=searchDesignation(row);if(results.has(query))return results.get(query);if(pending.has(query))return pending.get(query);const operation=(async()=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const res=await fetcher('https://images-api.nasa.gov/search?media_type=image&page_size=40&q='+encodeURIComponent(query),{signal:controller.signal});if(!res.ok)throw Error('Image archive unavailable (HTTP '+res.status+').');const data=await res.json();if(!Array.isArray(data?.collection?.items))throw Error('Unexpected image archive response.');const result={query,candidates:imageCandidates(data,query),checkedAt:new Date().toISOString()};results.set(query,result);return result;}finally{clearTimeout(timer);pending.delete(query);}})();pending.set(query,operation);return operation;}
